def count_pairs(n):
    import math
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // gcd(a, b)

    g = 2023
    L = math.factorial(n)

    if L % g != 0:
        return 0

    # We need to find the number of ordered pairs (a, b)
    # such that gcd(a, b) = g and lcm(a, b) = L.
    # This is equivalent to x*y = L/g and gcd(x, y) = 1.
    # The number of such pairs is 2^omega(L/g).

    target = L // g

    # Find omega(target)
    omega = 0
    d = 2
    temp = target
    while d * d <= temp:
        if temp % d == 0:
            omega += 1
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        omega += 1

    return 2**omega

results = []
for n in range(1, 60):
    num_pairs = count_pairs(n)
    if num_pairs <= 4000:
        results.append(n)

print("n values:", results)
print("Sum:", sum(results))
print("n values >= 34:", [n for n in results if n >= 34])
print("Sum of n >= 34:", sum([n for n in results if n >= 34]))
